<?php require 'helpers.php';require_leader();$pageTitle='Club dashboard';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$category=trim($_POST['category']??'');$description=trim($_POST['description']??'');if($name===''){flash('Club name is required.','error');redirect('dashboard.php');}$q=$pdo->prepare('INSERT INTO clubs(leader_id,name,category,description) VALUES(?,?,?,?)');$q->execute([current_user()['id'],$name,$category,$description]);flash('Your club profile has been created.');redirect('dashboard.php');}
$q=$pdo->prepare('SELECT * FROM clubs WHERE leader_id=? ORDER BY created_at DESC');$q->execute([current_user()['id']]);$clubs=$q->fetchAll();require 'header.php'; ?>
<section class="page-intro"><span class="eyebrow">CLUB LEADER SPACE</span><h1>Your dashboard</h1><p>Create and manage your club profile and campus events.</p></section>
<div class="dashboard-grid"><form class="form-card" method="post"><h2>Create a club profile</h2><?php csrf_field(); ?><label>Club name<input name="name" required></label><label>Category<input name="category" placeholder="Technology, Art, Sports..."></label><label>Description<textarea name="description" rows="4"></textarea></label><button class="btn primary full">Create club</button></form><div><h2>Your clubs</h2><?php if(!$clubs): ?><div class="empty">You have not created a club yet.</div><?php endif; ?><?php foreach($clubs as $c): ?><article class="list-card"><div><h3><?=e($c['name'])?></h3><p><?=e($c['category'])?></p></div><a class="text-link" href="manage-club.php?id=<?=$c['id']?>">Manage →</a></article><?php endforeach; ?></div></div>
<?php require 'footer.php'; ?>
